// Set month variables
const now = new Date();
// Get previous month (since we're reporting on completed month)
const reportMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);

const arabicMonths = [
  'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
  'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
];

function toArabicNumerals(num) {
  const arabicNumerals = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
  return num.toString().split('').map(d => arabicNumerals[parseInt(d)] || d).join('');
}

const year = reportMonth.getFullYear();
const month = reportMonth.getMonth();
const monthName = arabicMonths[month];
const monthEnglish = String(month + 1).padStart(2, '0');

const fileName = `تقرير_شهري_${year}-${monthEnglish}.docx`;

return {
  json: {
    month_arabic: monthName,
    month_number: month + 1,
    month_english: monthEnglish,
    year: year,
    year_arabic: toArabicNumerals(year),
    file_name: fileName,
    report_title: `التقرير الشهري للتحليل الجنائي المعمق - ${monthName} ${toArabicNumerals(year)}`,
    search_recency: 'month'
  }
};

