// Collect all sources for reference database
const violentNews = $('SERP - Violent Crime').item?.json?.news_results || [];
const financialNews = $('SERP - Financial Crime').item?.json?.news_results || [];
const traffickingNews = $('SERP - Human Trafficking').item?.json?.news_results || [];
const cyberNews = $('SERP - Cybercrime').item?.json?.news_results || [];
const aiNews = $('SERP - AI-Enabled Crime').item?.json?.news_results || [];
const childrenNews = $('SERP - Crimes Against Children').item?.json?.news_results || [];

const references = [];

const crimeTypeMap = {
  violent: violentNews,
  financial: financialNews,
  trafficking: traffickingNews,
  cyber: cyberNews,
  ai_enabled: aiNews,
  children: childrenNews
};

Object.entries(crimeTypeMap).forEach(([crimeType, news]) => {
  news.slice(0, 5).forEach(item => {
    if (item.link) {
      references.push({
        title: item.title,
        url: item.link,
        source_type: 'news',
        source_name: item.source?.name || item.source,
        publication_date: new Date().toISOString().split('T')[0],
        crime_type: [crimeType],
        region: ['Global'],
        geographical_scope: 'international'
      });
    }
  });
});

return {
  json: {
    operation: 'ADD_BATCH_REFERENCES',
    references: references.slice(0, 30)
  }
};

// Generate the complete Arabic monthly report
const monthVars = $('Set Month Variables').item.json;
const violentAnalysis = $('Perplexity - Violent Crime Analysis').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const financialAnalysis = $('Perplexity - Financial Crime Analysis').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const traffickingAnalysis = $('Perplexity - Trafficking Analysis').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const cyberAnalysis = $('Perplexity - Cybercrime Analysis').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const aiAnalysis = $('Perplexity - AI Crime Analysis').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const childrenAnalysis = $('Perplexity - Children Crime Analysis').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const executiveSummary = $('Perplexity - Executive Summary').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';

// Collect all citations
const allCitations = [
  ...($('Perplexity - Violent Crime Analysis').item?.json?.citations || []),
  ...($('Perplexity - Financial Crime Analysis').item?.json?.citations || []),
  ...($('Perplexity - Trafficking Analysis').item?.json?.citations || []),
  ...($('Perplexity - Cybercrime Analysis').item?.json?.citations || []),
  ...($('Perplexity - AI Crime Analysis').item?.json?.citations || []),
  ...($('Perplexity - Children Crime Analysis').item?.json?.citations || [])
];

const uniqueCitations = [...new Set(allCitations)];
let referencesSection = uniqueCitations.map((cite, i) => `${i + 1}. ${cite}`).join('\n');
if (!referencesSection) {
  referencesSection = 'المراجع متوفرة في نظام قاعدة البيانات المرجعية';
}

const report = `
